import {CATEGORIES,QUESTIONS,SOURCES,BANK_REVIEW} from './data.js';
import {freshState,today,datePlus,blueprint,categoryName,selectQuestions,dueQuestions,recordAnswer,grade,stats,streak,seenIds,validateBackup,pruneDaily,googleReviewUrl,reviewPrompt} from './engine.js';
const KEY='pn-practice-studio-v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={today:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 5h2m4 0h2"/>',practice:'<path d="m9 5 11 7-11 7V5Z"/>',review:'<path d="M4 9a8 8 0 1 1 0 6M4 4v5h5m3-1v5l3 2"/>',progress:'<path d="M4 20V10m8 10V4m8 16v-7"/>',guide:'<path d="M12 5v16M12 5C8 2 4 3 2 4v15c3-1 6-1 10 2 4-3 7-3 10-2V4c-3-1-6-1-10 1Z"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4V3Z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',pulse:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4Z"/><path d="m8 12 3 3 5-6"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 4H4v16h16v-6"/>'};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.spark}</svg>`;}
let state=freshState(),storageProblem=false,view='today',selection=[],numberResponse='',confidence='unsure',practiceCat='all',practiceCount=12,practiceMode='mixed',reviewFilter='due',guideTab='blueprint',resultIndex=-1;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);state=validateBackup(parsed);if(parsed.bankVersion!==BANK_REVIEW.version&&parsed.session?.mode==='exam'&&!parsed.session.completed&&Array.isArray(parsed.session.questions)&&Array.isArray(parsed.session.answers)){parsed.session.answers.forEach((a,i)=>{const q=parsed.session.questions[i];if(a&&q&&(QUESTIONS.some(x=>x.id===q.id)||q.type==='numeric'&&/^calc-\d+$/.test(q.id))&&(q.type==='numeric'?Number.isFinite(q.answer)&&typeof a.response==='string':Array.isArray(q.answer)&&Array.isArray(a.response))&&!state.history.some(h=>h.sessionId===parsed.session.id&&h.id===q.id))recordAnswer(state,q,a.response,{mode:'exam',sessionId:parsed.session.id,confidence:'sure',now:a.at||Date.now()});});}if(parsed.bankVersion===BANK_REVIEW.version&&parsed.session&&Array.isArray(parsed.session.questions)&&parsed.session.questions.every(q=>q&&typeof q.id==='string'&&Array.isArray(q.refs))&&parsed.session.questions.length<=150){state.session=parsed.session;}if(parsed.bankVersion===BANK_REVIEW.version&&parsed.daily&&typeof parsed.daily==='object')state.daily=parsed.daily;}}catch{storageProblem=true;}
state.bankVersion=BANK_REVIEW.version;
if(state.session&&!state.session.completed)view='session';
function save(){state.bankVersion=BANK_REVIEW.version;pruneDaily(state);try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageProblem=true;toast('Progress could not be saved. Export a backup before closing this page.');}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
const sourceLink=(id,label)=>{const s=SOURCES[id];return s?`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(label||s.name)} ${icon('external')}</a>`:'';};
function nav(v,label,i){const active=view===v||(v==='practice'&&['session','results'].includes(view));return `<button class="nav-item ${active?'active':''}" data-nav="${v}" ${active?'aria-current="page"':''}>${icon(i||v)}<span>${label}</span>${v==='review'&&dueQuestions(state).length?`<span class="nav-count">${dueQuestions(state).length}</span>`:''}</button>`;}
function title(eyebrow,heading,description='',extra=''){return `<header class="page-header"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1>${description?`<p>${description}</p>`:''}</div>${extra}</header>`;}
function shell(content){const s=stats(state);const province=state.settings.province==='ON'?'Ontario · RPN':state.settings.province==='BC'?'British Columbia · LPN':'Set your province';return `<aside class="sidebar"><a class="brand" href="#today" data-nav="today"><span class="brand-mark">${icon('pulse')}</span><span>PN Practice<span class="brand-sub">S T U D I O</span></span></a><div class="side-label">YOUR STUDY SPACE</div><nav aria-label="Main navigation">${nav('today','Today')}${nav('practice','Practice')}${nav('review','Review')}${nav('progress','Progress')}${nav('guide','Study guide','guide')}</nav><div class="sidebar-bottom"><div class="side-progress"><div class="tiny-label">BUILD YOUR FOUNDATION</div><strong>${new Set(state.history.filter(h=>!h.id.startsWith('calc-')).map(h=>h.id)).size}<span> / ${QUESTIONS.length}</span></strong><div class="track"><i style="width:${Math.min(100,new Set(state.history.filter(h=>!h.id.startsWith('calc-')).map(h=>h.id)).size/QUESTIONS.length*100)}%"></i></div><p>Original scenarios explored</p></div>${nav('settings','Your setup','settings')}<div class="local-note">${icon('shield')}<span>Progress stays on this device</span></div></div></aside><div class="workspace"><header class="topbar"><div class="top-context"><span class="status-pill">REx-PN practice</span><span class="top-separator">/</span><span>${esc(province)}</span></div><button class="avatar" data-nav="settings" aria-label="Open your setup">PN</button></header><main id="main" tabindex="-1">${storageProblem?'<div class="notice warning">Browser storage is unavailable or a saved record could not be read. Export your current progress before leaving.</div>':''}${state.session&&!state.session.completed&&view!=='session'?`<div class="resume-banner"><span>${state.session.mode==='exam'?'Timed session is running':'You have a practice session in progress'} · ${state.session.index}/${state.session.questions.length} answered</span><button class="btn small" data-action="resume">Resume session</button></div>`:''}${content}<footer class="app-footer"><span>Independent study companion · Original AI-authored practice</span><button data-action="about">About this question bank</button></footer></main></div>`;}
function home(){const d=today(),st=stats(state),due=dueQuestions(state).length,done=state.daily[d]?.completed,dailyDone=state.history.filter(h=>h.mode==='daily'&&h.day===d).length;const date=new Date().toLocaleDateString('en-CA',{weekday:'long',month:'long',day:'numeric'});const session=state.session&&!state.session.completed;const seen=seenIds(state),remaining=QUESTIONS.filter(q=>!seen.has(q.id)&&!state.excluded.includes(q.id)).length;
return title(date,'Your daily practice','A little practice. A deeper understanding.',`<span class="streak">${icon('spark')} ${streak(state)} day${streak(state)===1?'':'s'} in a row</span>`)+`<div class="home-grid"><section class="daily-card"><div class="daily-top"><span class="tag light">YOUR NEXT SESSION</span><span>01 / Practice</span></div><h2>${done?'Today’s session, complete.':'Build your clinical judgement.'}</h2><p>${done?'You showed up. Take a moment to review what you learned, or keep going with a focused set.':'New scenarios across the test plan. Previously answered questions stay in Review.'}</p><div class="session-spec"><span>${icon('guide')} ${Math.min(state.settings.goal,remaining)} new questions</span><span>${icon('clock')} About ${Math.round(state.settings.goal*1.7)} min</span></div><button class="btn lime" data-action="${session?'resume':done?'open-practice':'daily'}">${icon(done?'check':'practice')}${session?'Continue your session':done?'Choose another practice set':'Start today’s practice'}</button><div class="daily-line"><span>${done?'Daily goal complete':dailyDone?`${dailyDone} answered in today’s daily practice`:`${remaining} new scenarios remaining`}</span><span>Explanations included</span></div></section><aside class="next-card"><div class="eyebrow">02 / STRENGTHEN</div><div class="review-orbit">${icon('review')}<span>${due}</span></div><h2>${due?'Ready for a second look':'Make learning stick'}</h2><p>${due?`${due} scenario${due===1?' is':'s are'} due for spaced review. Revisit the reasoning, not just the answer.`:'After you practise, mistakes and uncertain answers will return here for another look.'}</p><button class="btn secondary" data-action="review-due" ${!due?'disabled':''}>Review due questions</button></aside></div><section class="stat-strip" aria-label="Your practice statistics"><div><span>Questions answered</span><strong>${st.total}<small>all practice sessions</small></strong></div><div><span>Fully correct</span><strong>${st.accuracy===null?'—':st.accuracy+'%'}<small>${st.total?`${st.exact} of ${st.total} responses`:'Your baseline starts here'}</small></strong></div><div><span>Practice this week</span><strong>${state.history.filter(h=>h.day>=datePlus(d,-6)).length}<small>last 7 calendar days</small></strong></div></section><div class="section-title"><h2>Choose a focus</h2><button class="text-button" data-nav="practice">All practice options ${icon('practice')}</button></div><div class="focus-grid">${CATEGORIES.slice(0,2).concat(CATEGORIES[5]).map(c=>focusCard(c)).join('')}</div><div class="foundation-note">${icon('guide')}<div><strong>Your exam, your plan.</strong><p>${state.settings.examDate?`Using the ${blueprint(state.settings)} test plan for your chosen date.`:'Set your exam date to select the 2022 or 2027 plan.'} The eight category midpoints are the same in both; detailed activity statements differ.</p></div><button class="text-button" data-nav="settings">Set up</button></div>`;}
function focusCard(c){return `<button class="focus-card" data-cat="${c.id}"><span class="category-mark" style="--cat:${c.color}">${String(CATEGORIES.indexOf(c)+1).padStart(2,'0')}</span><span class="focus-percent">${c.weight}% midpoint</span><h3>${esc(c.short)}</h3><p>${esc(c.focus)}</p><span class="focus-link">Practise this area ${icon('practice')}</span></button>`;}
function practice(){return title('PRACTICE ROOM','Choose your session','Go broad, focus on one area, or work through the numbers.')+`<div class="practice-grid"><section class="panel session-builder"><div class="panel-heading"><h2>Make a practice set</h2><span class="tag">TUTOR MODE</span></div><p>Submit an answer, explore the reasoning, then move on.</p><label class="field">Focus area<select id="practice-cat"><option value="all">All eight areas · balanced mix</option>${CATEGORIES.map(c=>`<option value="${c.id}" ${practiceCat===c.id?'selected':''}>${esc(categoryName(c,state.settings))}</option>`).join('')}</select></label><label class="field">Questions<select id="practice-count">${[8,12,20,30,40,50].map(n=>`<option ${practiceCount===n?'selected':''}>${n}</option>`).join('')}</select></label><div class="notice subtle">Unseen scenarios come first. When a category’s bank runs out, earlier scenarios return. Options are shuffled. Daily sessions use only unseen scenarios; calculation practice has its own lab.</div><button class="btn primary wide" data-action="custom">${icon('practice')} Start practice</button></section><div class="mode-stack"><section class="mode-card"><span class="mini-icon blue">123</span><div><h2>Calculation lab</h2><p>Weight-based doses, liquid concentrations, infusion timing and fluid allowance. Multi-step worked solutions included.</p><button class="text-button" data-action="calculations">Start 10 calculations ${icon('practice')}</button></div></section><section class="mode-card"><span class="mini-icon amber">${icon('clock')}</span><div><h2>Timed practice</h2><p>90 questions · 4-hour limit. One direction, no hints. Explanations unlock when the session ends.</p><button class="text-button" data-action="exam">Start timed session ${icon('practice')}</button></div></section><p class="muted small-copy">Timed practice uses a fixed set. It does not reproduce the exam’s computerized adaptive testing or predict a pass.</p></div></div><div class="section-title"><h2>The eight Client Needs areas</h2><span>${QUESTIONS.length} original scenarios + calculation templates</span></div><div class="category-grid">${CATEGORIES.map(c=>focusCard(c)).join('')}</div>`;}
function reviewPage(){const due=dueQuestions(state);const wrong=QUESTIONS.filter(q=>state.reviews[q.id]&&!state.reviews[q.id].exact&&!state.excluded.includes(q.id));const marked=QUESTIONS.filter(q=>state.bookmarks.includes(q.id)&&!state.excluded.includes(q.id));const excluded=QUESTIONS.filter(q=>state.excluded.includes(q.id));const rows=reviewFilter==='due'?due:reviewFilter==='mistakes'?wrong:reviewFilter==='bookmarks'?marked:excluded;
return title('THE SECOND LOOK','Turn mistakes into understanding','Review is scheduled for tomorrow, then 3, 7, 14 and 30 days after confident correct answers.')+`<div class="tab-row" role="group" aria-label="Review filters">${[['due',`Due now · ${due.length}`],['mistakes',`Last answer missed · ${wrong.length}`],['bookmarks',`Saved · ${marked.length}`],['excluded',`Set aside · ${excluded.length}`]].map(([id,t])=>`<button class="tab ${reviewFilter===id?'selected':''}" data-review="${id}" aria-pressed="${reviewFilter===id}">${t}</button>`).join('')}</div>${rows.length?`<div class="section-title"><p>${reviewFilter==='excluded'?'These questions are excluded from new sessions on this device.':`${rows.length} scenario${rows.length===1?'':'s'} in this collection`}</p>${reviewFilter!=='excluded'?`<button class="btn primary" data-action="review-set">Practise this collection</button>`:''}</div><div class="review-list">${rows.map(q=>{const c=CATEGORIES.find(c=>c.id===q.cat);return `<article class="review-row"><span class="category-dot" style="background:${c.color}"></span><div><span class="eyebrow">${c.short} · ${q.id}</span><h3>${esc(q.title)}</h3><p>${esc(q.stem)}</p>${state.notes[q.id]?`<span class="note-preview">Your note: ${esc(state.notes[q.id])}</span>`:''}</div>${reviewFilter==='excluded'?`<button class="btn secondary small" data-restore="${q.id}">Restore</button>`:`<button class="icon-button ${state.bookmarks.includes(q.id)?'bookmarked':''}" data-bookmark="${q.id}" aria-label="${state.bookmarks.includes(q.id)?'Unsave':'Save'} ${esc(q.title)}">${icon('bookmark')}</button>`}</article>`;}).join('')}</div>`:`<div class="empty-state">${icon(reviewFilter==='bookmarks'?'bookmark':'review')}<h2>${reviewFilter==='due'?'You’re all caught up':reviewFilter==='mistakes'?'No missed questions yet':reviewFilter==='bookmarks'?'Keep useful questions close':'No questions set aside'}</h2><p>${reviewFilter==='due'?'Your next review appears here when it is due. New practice is always available.':reviewFilter==='bookmarks'?'Save a question with the bookmark button while you practise.':'Build your history by completing a practice session.'}</p><button class="btn primary" data-nav="practice">Choose a practice set</button></div>`}`;}
function progress(){const st=stats(state),days=Array.from({length:7},(_,i)=>datePlus(today(),i-6)),counts=days.map(d=>state.history.filter(h=>h.day===d).length),max=Math.max(1,...counts);const reasons={};for(const h of state.history)if(h.reason)reasons[h.reason]=(reasons[h.reason]||0)+1;return title('YOUR LEARNING, OVER TIME','See where to focus','These are practice results, not a pass probability.')+`<section class="stat-strip standalone"><div><span>Questions answered</span><strong>${st.total}</strong></div><div><span>Fully correct</span><strong>${st.accuracy===null?'—':st.accuracy+'%'}</strong></div><div><span>Current streak</span><strong>${streak(state)}<small>days with at least one answer</small></strong></div></section><div class="progress-grid"><section class="panel"><div class="panel-heading"><h2>The last seven days</h2><span class="tag">${counts.reduce((a,b)=>a+b,0)} ANSWERS</span></div><div class="bar-chart" role="img" aria-label="Daily questions answered: ${days.map((d,i)=>d+': '+counts[i]).join(', ')}">${days.map((d,i)=>`<div class="bar-column"><span>${counts[i]}</span><div class="bar-space"><i style="height:${counts[i]/max*100}%;${counts[i]?'':'min-height:3px;background:var(--line)'}"></i></div><span>${new Date(d+'T12:00:00').toLocaleDateString('en',{weekday:'short'})}</span></div>`).join('')}</div></section><section class="panel"><h2>What tripped you up?</h2><p class="muted">Add a reason after an incorrect answer to spot recurring patterns.</p>${Object.keys(reasons).length?Object.entries(reasons).sort((a,b)=>b[1]-a[1]).map(([r,n])=>`<div class="reason-stat"><span>${esc(r)}</span><strong>${n}</strong></div>`).join(''):'<p class="empty-small">Your reflections will appear here.</p>'}</section></div><section class="panel"><div class="panel-heading"><h2>Performance by area</h2><span class="muted">Fully correct / attempted</span></div><div class="area-stats">${CATEGORIES.map(c=>{const h=state.history.filter(x=>x.cat===c.id),n=h.filter(x=>x.exact).length,p=h.length?Math.round(n/h.length*100):0;return `<div class="area-stat"><div><strong>${esc(categoryName(c,state.settings))}</strong><span>${h.length?`${n}/${h.length} · ${p}%`:'Not practised yet'}</span></div><div class="track"><i style="width:${p}%;background:${c.color}"></i></div><small>${h.length&&h.length<10?'Small sample — keep practising':`${c.weight}% test-plan midpoint`}</small></div>`;}).join('')}</div></section>`;}
function guide(){return title('A RELIABLE STARTING POINT','Your study guide','Use this practice space alongside your course material and the official resources.')+`<div class="tab-row" role="group" aria-label="Guide sections">${[['blueprint','The test plan'],['method','How to practise'],['sources','Sources & limits']].map(([id,t])=>`<button class="tab ${guideTab===id?'selected':''}" data-guide="${id}" aria-pressed="${guideTab===id}">${t}</button>`).join('')}</div>${guideTab==='blueprint'?`<div class="notice"><strong>${blueprint(state.settings)} plan selected.</strong> The 2027 plan applies from January 1, 2027. Both plans use the same category midpoints and ±3 percentage-point ranges; activity statements change. This bank has not been mapped to every activity statement. ${sourceLink('plan','Read the official plans')}</div><section class="panel"><div class="blueprint-table"><div class="blueprint-head"><span>Client Needs area</span><span>Range</span><span>Midpoint</span></div>${CATEGORIES.map(c=>`<div class="blueprint-row"><div><span class="category-dot" style="background:${c.color}"></span><strong>${esc(categoryName(c,state.settings))}</strong><p>${esc(c.focus)}</p></div><span>${c.weight-3}–${c.weight+3}%</span><strong>${c.weight}%</strong></div>`).join('')}</div></section><div class="section-title"><h2>What to look for</h2></div><div class="lesson-grid">${CATEGORIES.map(c=>`<article class="panel lesson"><span class="eyebrow" style="color:${c.color}">${c.short}</span><h3>${esc(c.focus)}</h3><p>${esc(c.lesson)}</p><button class="text-button" data-cat="${c.id}">Practise this area</button></article>`).join('')}</div>`:guideTab==='method'?`<div class="lesson-grid"><article class="panel"><span class="step-number">01</span><h2>Practise with intent</h2><p>Read the whole scenario. Identify the client’s immediate concern, the task being asked and whether it asks for the first, best or most urgent action.</p><p>Try a daily set before checking explanations. Use focused sets to repair a specific gap.</p></article><article class="panel"><span class="step-number">02</span><h2>Explain your choice</h2><p>Review the rationale for every option, including when you were correct. Ask why a plausible action is less appropriate at this moment.</p><p>Mark whether the difficulty was knowledge, prioritization, reading, calculation or scope. Write one short takeaway in your own words.</p></article><article class="panel"><span class="step-number">03</span><h2>Return to the hard parts</h2><p>Missed or uncertain scenarios return the next day. Confident correct responses move through 1, 3, 7, 14 and 30-day intervals.</p><p>This is a simple study schedule, not a clinically or psychometrically validated adaptive algorithm.</p></article><article class="panel"><span class="step-number">04</span><h2>Prepare for the real format</h2><p>The actual REx-PN uses computerized adaptive testing, 90–150 items and a four-hour limit. You cannot go back after submitting. Use the official preview and tutorial to learn the interface.</p><p>Here, timed practice is fixed-length and all items count toward practice results. Graphic item interaction and the actual CAT scoring model are not reproduced.</p>${sourceLink('prepare')}</article></div><div class="notice"><strong>Multiple-response scoring in this app:</strong> one point for each selected correct option, minus one for each selected incorrect option, with a floor of zero; divided by the number of correct options. “Fully correct” requires the exact answer set. The official exam awards partial credit for select-all-that-apply items from January 2026; this app’s learning score is not an official scaled score. ${sourceLink('faq','Official scoring information')}</div>`:`<section class="panel provenance"><span class="tag">QUESTION BANK ${esc(BANK_REVIEW.version)}</span><h2>Original practice, transparent limits.</h2><p>This app contains <strong>${QUESTIONS.length} original AI-authored scenarios</strong> and <strong>5 arithmetic templates</strong>. It includes single-choice, select-all-that-apply, numeric entry and text/table exhibits. It does not contain recalled, leaked or licensed commercial exam questions.</p><p><strong>Independent AI review is not qualified clinical, regulatory or psychometric validation.</strong> It is a foundation for additional study, not a complete REx-PN preparation course or a substitute for an approved nursing programme, current textbooks and provincial standards. Items are checked for answer defensibility, realistic context and plausible alternative actions. Difficulty labels are editorial judgements, not measured exam difficulty.</p><p>Links beside rationales are further-reading references; they are not evidence that each scenario has been individually validated. Where a reference uses US terminology, Canadian provincial legislation and regulator standards take precedence for scope and practice rules.</p><p>Content was assembled October 1, 2026. Daily sessions use only unseen scenarios and stop when none remain. Review and focused practice let you revisit earlier cases. Calculation variants change numbers within five templates; they do not represent new clinical scenarios.</p><p>Not affiliated with or endorsed by NCSBN, CNO or BCCNM. REx-PN is a mark of NCSBN. No exam success guarantee is made.</p></section><div class="section-title"><h2>Go to the source</h2><span>Official resources first</span></div><div class="source-grid">${Object.entries(SOURCES).map(([id,s])=>`<article class="source-card"><span class="eyebrow">${esc(s.kind)}</span>${sourceLink(id)}</article>`).join('')}</div><section class="panel"><h2>Which province?</h2><p>Your province setting selects supplementary regulator resources. REx-PN does not examine provincial health systems, history, policies or laws; Ontario jurisprudence is assessed separately. General consent, confidentiality and professional judgement remain relevant.</p><p>Ontario uses RPN for registered practical nurse. British Columbia uses LPN for licensed practical nurse; RPN in BC refers to a different nursing profession.</p><div class="source-links">${sourceLink('cno')}${sourceLink('bc')}</div></section>`}`;}
function settings(){return title('MAKE IT YOURS','Your setup','Choose the context for your study. No account or API key is needed.')+`<div class="settings-grid"><form class="panel" id="settings-form"><h2>Study preferences</h2><label class="field">Province<select name="province"><option value="">Not chosen yet</option><option value="ON" ${state.settings.province==='ON'?'selected':''}>Ontario · Registered Practical Nurse</option><option value="BC" ${state.settings.province==='BC'?'selected':''}>British Columbia · Licensed Practical Nurse</option></select></label><label class="field">Exam date <span class="optional">optional</span><input type="date" name="examDate" value="${esc(state.settings.examDate)}"></label><p class="field-help">Before January 1, 2027: 2022 plan. From January 1, 2027: 2027 plan. If blank, today’s date selects the plan.</p><label class="field">Daily session size<select name="goal">${[8,12,20,30,50].map(n=>`<option value="${n}" ${state.settings.goal===n?'selected':''}>${n} questions · about ${Math.round(n*1.7)} minutes</option>`).join('')}</select></label><button class="btn primary" type="submit">Save preferences</button></form><div><section class="panel"><h2>Your progress belongs to you</h2><p>Practice history, notes and saved questions are stored in this browser on this device. There is no automatic sync. Private browsing or clearing site data may erase progress.</p><div class="button-row"><button class="btn secondary" data-action="export">${icon('download')} Export backup</button><button class="btn secondary" data-action="import">Import backup</button></div><input type="file" id="backup-file" accept="application/json,.json" hidden><p class="field-help">Import replaces local history after confirmation. Active sessions are not imported. Export first to keep a copy.</p></section><section class="panel danger-zone"><h2>Start over</h2><p>Reset all study data stored by this app on this device.</p><button class="text-button danger" data-action="reset">Reset my progress</button></section></div></div>`;}
function formatTime(seconds){const n=Math.max(0,Math.floor(seconds));const h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${m}:${String(s).padStart(2,'0')}`;}
function timerText(){const s=state.session;if(!s)return '';return formatTime(s.mode==='exam'?(s.deadline-Date.now())/1000:(Date.now()-s.startedAt)/1000);}
function currentQuestion(){return state.session?.questions[state.session.index];}
function questionPage(){const s=state.session;if(!s||s.completed)return resultsPage();const q=currentQuestion(),answered=s.answers[s.index],c=CATEGORIES.find(c=>c.id===q.cat),exam=s.mode==='exam';if(answered){selection=Array.isArray(answered.response)?answered.response:[];numberResponse=typeof answered.response==='string'?answered.response:'';}const valid=q.type==='numeric'?/^\d+(?:[.,]\d+)?$/.test(numberResponse.trim()):selection.length>0;
return `<div class="session-top"><button class="text-button" data-action="leave-session">Save & leave</button><span class="session-mode">${exam?'TIMED PRACTICE':s.mode==='daily'?'DAILY PRACTICE':s.mode==='calculations'?'CALCULATION LAB':'TUTOR PRACTICE'}</span><span class="timer">${icon('clock')}<span id="timer">${timerText()}</span>${exam?' left':''}</span></div><div class="session-progress"><div class="track"><i style="width:${s.index/s.questions.length*100}%"></i></div><span>${s.index+1} / ${s.questions.length}</span></div><div class="question-layout"><section class="question-main"><div class="question-meta"><span class="tag" style="color:${c.color}">${esc(c.short)}</span><span>${q.type==='multiple'?'Select all that apply':q.type==='numeric'?'Numeric entry':'Single best answer'}</span><button class="icon-button ${state.bookmarks.includes(q.id)?'bookmarked':''}" data-bookmark="${q.id}" aria-label="${state.bookmarks.includes(q.id)?'Unsave':'Save'} question" ${q.type==='numeric'?'hidden':''}>${icon('bookmark')}</button></div><h1 class="question-title">${esc(q.stem)}</h1>${q.exhibit?`<div class="exhibit"><h2>Client record</h2><table><thead><tr>${q.exhibit[0].map(v=>`<th scope="col">${esc(v)}</th>`).join('')}</tr></thead><tbody>${q.exhibit.slice(1).map(row=>`<tr>${row.map((v,i)=>i===0?`<th scope="row">${esc(v)}</th>`:`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}${q.type==='multiple'?'<p class="answer-instruction">Choose every applicable option. Partial learning credit is available.</p>':''}<form id="answer-form">${q.type==='numeric'?`<label class="numeric-answer">Your answer<div><input id="numeric-response" type="text" inputmode="decimal" autocomplete="off" value="${esc(numberResponse)}" ${answered?'disabled':''} aria-describedby="numeric-unit" required><span id="numeric-unit">${q.unit}</span></div></label>`:`<fieldset class="answers"><legend class="sr-only">${q.type==='multiple'?'Select all correct answers':'Select the best answer'}</legend>${q.options.map((o,i)=>{const chosen=selection.includes(i),correct=answered&&q.answer.includes(i),wrong=answered&&chosen&&!correct;return `<label class="answer-option ${chosen?'chosen':''} ${correct?'correct':''} ${wrong?'incorrect':''}"><input type="${q.type==='multiple'?'checkbox':'radio'}" name="answer" value="${i}" ${chosen?'checked':''} ${answered?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span class="option-text">${esc(o)}</span>${correct?icon('check'):wrong?icon('close'):''}</label>`;}).join('')}</fieldset>`}${!answered?`<div class="submit-row">${!exam?`<div class="confidence"><span>How sure are you?</span><div role="group" aria-label="Confidence"><button type="button" data-confidence="unsure" class="${confidence==='unsure'?'selected':''}" aria-pressed="${confidence==='unsure'}">Still learning</button><button type="button" data-confidence="sure" class="${confidence==='sure'?'selected':''}" aria-pressed="${confidence==='sure'}">Confident</button></div></div>`:'<span class="muted">You cannot return after submitting.</span>'}<button class="btn primary" type="submit" id="submit-answer" ${valid?'':'disabled'}>${exam?'Submit & continue':'Check answer'}</button></div>`:''}</form>${answered&&!exam?feedback(q,answered):''}${answered&&!exam?`<div class="next-row"><button class="btn primary" data-action="next">${s.index===s.questions.length-1?'Finish session':'Next question'}</button></div>`:''}</section><aside class="question-aside"><section class="panel thinking-card"><span class="eyebrow">YOUR THINKING SPACE</span><h2>${exam?'One question at a time.':'Pause. Notice. Decide.'}</h2><ol><li>What is the question asking?</li><li>Which finding matters most?</li><li>What is safe in this situation?</li></ol><p>${exam?'Explanations are saved for the end of this session.':'An action can be useful without being the best first action.'}</p></section><details class="panel calculator"><summary>${icon('settings')} Calculator</summary><div class="calc-inputs"><input type="number" step="any" id="calc-a" aria-label="First number" placeholder="0"><select id="calc-op" aria-label="Operation"><option value="+">+</option><option value="-">−</option><option value="*">×</option><option value="/">÷</option></select><input type="number" step="any" id="calc-b" aria-label="Second number" placeholder="0"></div><button class="btn secondary small wide" data-action="calculate">Calculate</button><output id="calc-result" aria-live="polite">—</output></details><p class="aside-note">${q.id}<br>Original practice · ${q.type==='numeric'?'Calculation practice':'Not an actual exam item'}</p>${exam?'<button class="text-button danger" data-action="end-exam">End & review session</button>':''}</aside></div>`;}
function feedback(q,a,readOnly=false){const g=grade(q,a.response),selected=Array.isArray(a.response)?a.response:[];const title=g.exact?'Correct. Keep the reasoning.':g.points>0?'Partly correct. Let’s unpack it.':'A useful one to revisit.';const refs=q.refs.some(id=>['cno','bc','bcmed'].includes(id))?(state.settings.province==='ON'?['cno']:state.settings.province==='BC'?['bc']:['cno','bc']):q.refs;return `<section class="feedback ${g.exact?'success':'learning'}" aria-label="Answer explanation"><div class="feedback-heading"><span class="feedback-symbol">${icon(g.exact?'check':'guide')}</span><div><h2 id="feedback-heading" tabindex="-1">${title}</h2><p>${q.type==='multiple'?`Learning credit: ${Math.round(g.points*100)}%. Fully correct requires the exact set.`:q.type==='numeric'?`Your answer: ${esc(a.response)} ${q.unit} · Expected: ${q.answer} ${q.unit}`:'Focus on why this answer fits the scenario.'}</p></div></div><div class="takeaway"><span class="eyebrow">THE TAKEAWAY</span><p>${esc(q.takeaway)}</p></div>${q.type==='numeric'?`<div class="worked-solution"><h3>Work it through</h3><p>${esc(q.solution)}</p></div>`:`<div class="rationales"><h3>Why each option matters</h3>${q.options.map((o,i)=>`<div class="rationale"><span class="rationale-letter ${q.answer.includes(i)?'right':''}">${String.fromCharCode(65+i)}</span><div><div class="rationale-label">${q.answer.includes(i)?'Correct option':'Not the best choice'}${selected.includes(i)?' · Your selection':''}</div><p>${esc(q.why[i])}</p></div></div>`).join('')}</div>`}<div class="source-links"><span>Further reading</span>${refs.map(id=>sourceLink(id)).join('')}</div>${externalReviewActions(q)}${!readOnly?`<div class="reflection">${!g.exact?`<label class="field">What made this difficult?<select id="error-reason"><option value="">Choose a reason (optional)</option>${['Knowledge gap','Prioritization','Misread the question','Calculation or units','Scope or delegation','Overthinking'].map(r=>`<option ${a.reason===r?'selected':''}>${r}</option>`).join('')}</select></label>`:''}${q.type!=='numeric'?`<label class="field">A note for next time<textarea id="question-note" rows="2" maxlength="3000" placeholder="One idea in your own words…">${esc(state.notes[q.id]||'')}</textarea></label><button class="text-button" data-exclude="${q.id}">Set this question aside if something seems wrong</button>`:''}</div>`:''}</section>`;}
function externalReviewActions(q){return `<div class="external-review"><h3>Compare with external sources</h3><div class="button-row"><a class="btn secondary small" href="${esc(googleReviewUrl(q,state.settings))}" target="_blank" rel="noopener noreferrer">${icon('external')} Search Google</a><button class="btn secondary small" data-copy-review="${esc(q.id)}">${icon('guide')} Copy review prompt</button></div><p>Search sends the question and options to Google without the answer key. Copy includes the proposed answer and explanations for a critical review. Google may show an AI answer; read the supporting sources. This does not verify or change your result.</p></div>`;}
function manualCopyPrompt(text){
 const dialog=document.createElement('dialog');dialog.className='confirm-dialog copy-dialog';dialog.setAttribute('aria-labelledby','copy-review-title');
 dialog.innerHTML='<h2 id="copy-review-title">Copy review prompt</h2><p>Select and copy this text, then paste it into your chosen AI or search service.</p><label class="field">Question and proposed explanation<textarea id="review-copy-text" rows="12" readonly></textarea></label><div class="button-row"><button class="btn primary" data-close-copy>Done</button></div>';
 const box=dialog.querySelector('textarea');box.value=text;document.body.append(dialog);dialog.querySelector('[data-close-copy]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();box.focus();box.select();
}
async function copyQuestionReview(id){
 const s=state.session;if(!s||(s.mode==='exam'&&!s.completed))return;
 const index=s.questions.findIndex(q=>q.id===id);if(index<0||!s.answers[index])return;
 const text=reviewPrompt(s.questions[index],state.settings);
 try{if(!window.navigator?.clipboard?.writeText)throw Error('Manual copy needed');await window.navigator.clipboard.writeText(text);toast('Review prompt copied. Paste it into your chosen AI or search service.');}
 catch{manualCopyPrompt(text);}
}
function resultsPage(){const s=state.session;if(!s)return home();const answers=s.answers.filter(Boolean),correct=answers.filter(a=>a.exact).length,points=answers.reduce((sum,a)=>sum+a.points,0),missed=s.questions.filter((q,i)=>s.answers[i]&&!s.answers[i].exact);return title('SESSION COMPLETE','Good work showing up.','Keep the understanding. Bring the difficult questions back.')+`<section class="results-hero"><span class="result-seal">${icon('check')}</span><div><div class="eyebrow">${s.mode==='exam'?'TIMED PRACTICE RESULTS':'YOUR SESSION IN REVIEW'}</div><h2>${correct}<span> / ${answers.length} fully correct</span></h2><p>${answers.length} of ${s.questions.length} questions answered · ${formatTime(((s.finishedAt||Date.now())-s.startedAt)/1000)} elapsed</p><p>${answers.length?Math.round(points/answers.length*100):0}% average learning credit across answered questions. Not a pass prediction.</p></div></section>${s.timedOut?'<div class="notice warning">The four-hour limit was reached. Unanswered questions are shown as not answered below and are excluded from the practice percentage.</div>':''}<div class="button-row results-actions"><button class="btn primary" data-nav="today">Back to today</button><button class="btn secondary" data-nav="practice">More practice</button><button class="btn secondary" data-nav="review">Open review queue</button></div><div class="section-title"><h2>Review every answer</h2><span>${missed.length} to revisit</span></div><div class="results-list">${s.questions.map((q,i)=>{const a=s.answers[i];return `<details class="panel result-item" ${resultIndex===i?'open':''}><summary><span class="result-status ${a?.exact?'right':a?'wrong':''}">${a?.exact?icon('check'):a?icon('review'):'—'}</span><span><strong>${esc(q.title)}</strong><small>${CATEGORIES.find(c=>c.id===q.cat).short} · ${a?a.exact?'Fully correct':a.points>0?'Partly correct':'Revisit':'Not answered'}</small></span><span class="result-number">${String(i+1).padStart(2,'0')}</span></summary><p class="result-stem">${esc(q.stem)}</p>${a?feedback(q,a,true):'<p>This question was not answered in this session.</p>'}</details>`;}).join('')}</div>`;}
function render({focus=false}={}){let content;switch(view){case'practice':content=practice();break;case'review':content=reviewPage();break;case'progress':content=progress();break;case'guide':content=guide();break;case'settings':content=settings();break;case'session':content=questionPage();break;case'results':content=resultsPage();break;default:content=home();}$('#app').innerHTML=shell(content);document.title=`${view==='session'?'Practice':view.charAt(0).toUpperCase()+view.slice(1)} · PN Practice Studio`;if(focus)$('#main').focus({preventScroll:true});}
function navigate(next){view=next;resultIndex=-1;render({focus:true});window.scrollTo(0,0);}
function showConfirm(title,body,accept,fn){const dialog=document.createElement('dialog');dialog.className='confirm-dialog';dialog.innerHTML=`<h2>${esc(title)}</h2><p>${esc(body)}</p><div class="button-row"><button class="btn secondary" data-cancel>Cancel</button><button class="btn primary" data-confirm>${esc(accept)}</button></div>`;document.body.append(dialog);dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.querySelector('[data-confirm]').onclick=()=>{dialog.close();fn();};dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();}
function startSession(mode,cat='all',count=12,force=false){if(state.session&&!state.session.completed&&!force){showConfirm('Replace the current session?','Submitted tutor answers are already saved. An unfinished timed session will be ended and its submitted answers saved before the new session starts.','Start new session',()=>{finishSession(false);startSession(mode,cat,count,true);});return;}
 const day=today();if(mode==='daily'&&state.daily[day]?.completed){toast('Today’s daily set is complete. Choose another practice mode.');navigate('practice');return;}
 let questions;const seed=mode==='daily'?`${day}:daily`:`${Date.now()}:${Math.random()}`;
 if(mode==='daily'&&Array.isArray(state.daily[day]?.questions)){const saved=state.daily[day];questions=saved.questions.filter(q=>!saved.answered?.includes(q.id)&&!state.excluded.includes(q.id));}
 else{questions=selectQuestions(state,{mode,count,cat,day,seed});if(mode==='daily')state.daily[day]={questions,answered:[],completed:false};}
 if(!questions.length){toast(mode==='daily'?'You have completed every available new scenario. Use Review or a focused practice set.':'There are no questions available in this collection.');return;}
 const now=Date.now();state.session={id:`session-${now}`,mode,questions,index:0,answers:[],startedAt:now,deadline:mode==='exam'?now+4*60*60*1000:null,completed:false,day};selection=[];numberResponse='';confidence='unsure';save();navigate('session');}
function submitAnswer(){const s=state.session,q=currentQuestion();if(!s||s.completed||s.answers[s.index])return;const response=q.type==='numeric'?numberResponse:[...selection];if(q.type==='numeric'&&!/^\d+(?:[.,]\d+)?$/.test(response.trim())||q.type!=='numeric'&&!response.length)return;const now=Date.now();let answer;
 if(s.mode==='exam'){answer={...grade(q,response),response,confidence:'sure',at:now};}else answer=recordAnswer(state,q,response,{confidence,sessionId:s.id,mode:s.mode,now});
 s.answers[s.index]=answer;
 if(s.mode==='daily'){const d=state.daily[s.day];if(d&&!d.answered.includes(q.id))d.answered.push(q.id);}
 save();if(s.mode==='exam')nextQuestion();else{render();$('#feedback-heading')?.focus({preventScroll:true});$('#feedback-heading')?.scrollIntoView({behavior:'smooth',block:'nearest'});}}
function nextQuestion(){const s=state.session;if(!s?.answers[s.index])return;if(s.index>=s.questions.length-1){finishSession();return;}s.index++;selection=[];numberResponse='';confidence='unsure';save();render({focus:true});window.scrollTo(0,0);}
function finishSession(show=true){const s=state.session;if(!s||s.completed){if(show)navigate('results');return;}if(s.mode==='exam'&&!s.committed){s.answers.forEach((a,i)=>{if(a)recordAnswer(state,s.questions[i],a.response,{confidence:a.confidence,sessionId:s.id,mode:s.mode,now:a.at});});s.committed=true;}s.completed=true;s.finishedAt=Date.now();if(s.mode==='daily'&&state.daily[s.day])state.daily[s.day].completed=state.daily[s.day].answered.length>=state.daily[s.day].questions.length;save();if(show)navigate('results');}
function toggleBookmark(id){if(!QUESTIONS.some(q=>q.id===id))return;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();render();}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el||el.disabled)return;
 if(el.dataset.copyReview){void copyQuestionReview(el.dataset.copyReview);return;}
 if(el.dataset.nav){e.preventDefault();navigate(el.dataset.nav);return;}
 if(el.dataset.cat){practiceCat=el.dataset.cat;navigate('practice');return;}
 if(el.dataset.bookmark){toggleBookmark(el.dataset.bookmark);return;}
 if(el.dataset.review){reviewFilter=el.dataset.review;render();return;}
 if(el.dataset.guide){guideTab=el.dataset.guide;render();return;}
 if(el.dataset.confidence){confidence=el.dataset.confidence;document.querySelectorAll('[data-confidence]').forEach(b=>{b.classList.toggle('selected',b.dataset.confidence===confidence);b.setAttribute('aria-pressed',String(b.dataset.confidence===confidence));});return;}
 if(el.dataset.exclude){const id=el.dataset.exclude;showConfirm('Set this question aside?','It will be excluded from future sessions on this device. You can restore it from Review. No report is sent to a third party.','Set aside',()=>{state.excluded=[...new Set([...state.excluded,id])];save();toast('Question set aside. Restore it in Review whenever you like.');});return;}
 if(el.dataset.restore){state.excluded=state.excluded.filter(id=>id!==el.dataset.restore);save();render();return;}
 switch(el.dataset.action){case'daily':startSession('daily','all',state.settings.goal);break;case'resume':navigate(state.session?.completed?'results':'session');break;case'open-practice':navigate('practice');break;case'custom':startSession('mixed',practiceCat,practiceCount);break;case'calculations':startSession('calculations','pharmacology',10);break;case'exam':showConfirm('Begin timed practice?','90 fixed questions, up to 4 hours. The timer continues if you leave or close this page. Submitted answers cannot be changed; explanations unlock at the end. This is not the actual CAT exam.','Begin session',()=>startSession('exam','all',90));break;case'review-due':startSession('review','all',20);break;case'review-set':startSession(reviewFilter==='due'?'review':reviewFilter,'all',40);break;case'leave-session':save();navigate('today');break;case'next':nextQuestion();break;case'end-exam':showConfirm('End this timed session?','Your submitted answers will be saved and the explanations unlocked. Unanswered questions will not count in your practice percentage.','End & review',()=>finishSession());break;case'about':guideTab='sources';navigate('guide');break;case'export':{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`pn-practice-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported. Keep it somewhere safe.');break;}case'import':$('#backup-file').click();break;case'reset':showConfirm('Reset all local progress?','This removes history, notes, saved questions and preferences from this browser. Export a backup first if you want to keep them.','Reset progress',()=>{state=freshState();save();navigate('today');toast('Your study space has been reset.');});break;case'calculate':{const av=$('#calc-a').value,bv=$('#calc-b').value,a=Number(av),b=Number(bv),op=$('#calc-op').value;const out=op==='+'?a+b:op==='-'?a-b:op==='*'?a*b:b===0?NaN:a/b;$('#calc-result').textContent=!av||!bv?'Enter two numbers':Number.isFinite(out)?String(Number(out.toPrecision(12))):'Cannot divide by zero';break;}}
});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='practice-cat')practiceCat=t.value;if(t.id==='practice-count')practiceCount=Number(t.value);
 if(t.name==='answer'){const q=currentQuestion();selection=q.type==='multiple'?[...document.querySelectorAll('input[name="answer"]:checked')].map(x=>Number(x.value)):[Number(t.value)];document.querySelectorAll('.answer-option').forEach(l=>l.classList.toggle('chosen',l.querySelector('input').checked));$('#submit-answer').disabled=!selection.length;}
 if(t.id==='error-reason'){const s=state.session,a=s.answers[s.index];a.reason=t.value;const h=state.history.findLast(h=>h.id===currentQuestion().id&&h.sessionId===s.id);if(h)h.reason=t.value;save();}
 if(t.id==='backup-file'&&t.files[0]){const file=t.files[0];if(file.size>10*1024*1024){toast('This backup is too large (maximum 10 MB).');t.value='';return;}file.text().then(text=>{const backup=validateBackup(JSON.parse(text));showConfirm('Replace local progress?','This imports the backup’s history, notes, bookmarks and preferences. Your current local data and active session will be replaced.','Import backup',()=>{state=backup;save();navigate('today');toast('Backup imported.');});}).catch(()=>toast('Unable to import: choose a valid PN Practice Studio JSON backup.'));t.value='';}
});
document.addEventListener('input',e=>{if(e.target.id==='numeric-response'){numberResponse=e.target.value;$('#submit-answer').disabled=!/^\d+(?:[.,]\d+)?$/.test(numberResponse.trim());}if(e.target.id==='question-note'){state.notes[currentQuestion().id]=e.target.value;save();}});
document.addEventListener('submit',e=>{if(e.target.id==='answer-form'){e.preventDefault();submitAnswer();}if(e.target.id==='settings-form'){e.preventDefault();const form=new FormData(e.target);state.settings={province:form.get('province'),examDate:form.get('examDate'),goal:Number(form.get('goal'))};save();render();toast('Preferences saved. Your next daily set will use the new size.');}});
document.addEventListener('keydown',e=>{if(view!=='session'||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||document.querySelector('dialog[open]'))return;const n=Number(e.key);if(n>=1&&n<=5&&!state.session.answers[state.session.index]){const input=document.querySelector(`input[name="answer"][value="${n-1}"]`);if(input){e.preventDefault();input.click();}}});
setInterval(()=>{const s=state.session;if(!s||s.completed)return;if(s.mode==='exam'&&Date.now()>=s.deadline){s.timedOut=true;finishSession();toast('Time is up. Your submitted answers have been saved.');return;}if($('#timer'))$('#timer').textContent=timerText();},1000);
// Optional browser-agent access; uses exactly the same state as the visible UI.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_practice_progress',title:'Read practice progress',description:'Read device-local practice totals, due reviews and the selected exam plan.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('No parameters accepted.');return {...stats(state),due:dueQuestions(state).length,plan:blueprint(state.settings),province:state.settings.province};}},{name:'navigate_practice_section',title:'Open study section',description:'Navigate to a study section without starting or answering a session.',inputSchema:{type:'object',properties:{section:{type:'string',enum:['today','practice','review','progress','guide','settings']}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).length!==1||!['today','practice','review','progress','guide','settings'].includes(input.section))throw Error('Invalid section.');navigate(input.section);return {section:view};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
render();
